// @FIGURE_CODE_BEGIN
(function () {
  var W = 720, H = 290;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var geo = draw.group();
  var alg = draw.group();

  // ── geometry constants ────────────────────────────────────────────────
  var R = 62, CY = 122, PW = 240;
  var U = { x: 0.5, y: -Math.sqrt(3) / 2 };            // line direction (~60° up-right)
  var N = { x: -Math.sqrt(3) / 2, y: -0.5 };           // unit normal (up-left)
  var COLORS = ['#EE7A20', '#2DBE2D', '#C1252E'];
  var BLUE = '#1F6FA8';
  var CANON = [1.6, 1.0, 0.4];
  var CAP = ['No solutions', 'One solution', 'Two solutions'];
  var COUNTCOL = ['#c0392b', '#222222', '#1a8a3a'];

  // ── state ─────────────────────────────────────────────────────────────
  var offset = 1.6, active = 0, showDist = false, mode = 'geo';

  function panelCx(i) { return i * PW + 132; }
  function countFor(dU) { if (Math.abs(dU - 1) <= 0.025) return 1; return dU < 1 ? 2 : 0; }

  // Liang–Barsky clip of an infinite line to a box → [t0,t1] or null
  function clipLine(px, py, ux, uy, box) {
    var t0 = -1e5, t1 = 1e5;
    var p = [-ux, ux, -uy, uy];
    var q = [px - box.x0, box.x1 - px, py - box.y0, box.y1 - py];
    for (var i = 0; i < 4; i++) {
      if (Math.abs(p[i]) < 1e-9) { if (q[i] < 0) return null; }
      else {
        var t = q[i] / p[i];
        if (p[i] < 0) { if (t > t0) t0 = t; } else { if (t < t1) t1 = t; }
      }
    }
    return (t0 > t1) ? null : [t0, t1];
  }

  function arrowHead(g, x, y, dx, dy, color, len, half) {
    var bx = x - dx * len, by = y - dy * len;
    var px = -dy * half, py = dx * half;
    g.polygon(x + ',' + y + ' ' + (bx + px) + ',' + (by + py) + ' ' + (bx - px) + ',' + (by - py))
      .fill(color).stroke('none');
  }

  function label(g, str, x, y, o) {
    o = o || {};
    var t = g.text(str).font({ family: o.family || 'sans-serif', size: o.size || 12, anchor: 'middle' });
    t.fill(o.fill || '#222');
    if (o.italic) t.font({ style: 'italic' });
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.2, 'stroke-linejoin': 'round' });
    t.center(x, y);
    return t;
  }

  // ── geometric view ────────────────────────────────────────────────────
  function drawLineInBox(g, P0, box, width) {
    var cl = clipLine(P0.x, P0.y, U.x, U.y, box);
    if (!cl) return;
    var A = { x: P0.x + U.x * cl[0], y: P0.y + U.y * cl[0] };
    var B = { x: P0.x + U.x * cl[1], y: P0.y + U.y * cl[1] };
    var ln = g.line(A.x, A.y, B.x, B.y).stroke({ color: BLUE, width: width, linecap: 'round' });
    var hl = Math.max(7, width * 5), hw = Math.max(3, width * 2);
    arrowHead(g, B.x, B.y, U.x, U.y, BLUE, hl, hw);
    arrowHead(g, A.x, A.y, -U.x, -U.y, BLUE, hl, hw);
    return ln;
  }

  function renderGeometric() {
    for (var i = 0; i < 3; i++) {
      (function (i) {
        var g = geo.group();
        var cx = panelCx(i);
        var dU = (i === active) ? offset : CANON[i];
        var d = dU * R;
        var P0 = { x: cx + N.x * d, y: CY + N.y * d };
        var box = { x0: i * PW + 10, x1: i * PW + 230, y0: 12, y1: 206 };

        var ln = drawLineInBox(g, P0, box, 2.3);
        if (ln) {
          ln.css('cursor', 'pointer');
          ln.on('mousemove', function (e) { showTooltip('Line y = mx + b — slide it parallel to itself with the offset control', e); })
            .on('mouseleave', hideTooltip)
            .on('click', function () {
              showPopup('The line', 'All three lines have the same slope; only their distance from the circle centre differs. Sliding a line parallel to itself changes nothing but d, yet it flips the system between 0, 1 and 2 solutions.');
            });
        }

        var circ = g.circle(2 * R).center(cx, CY).fill('none').stroke({ color: COLORS[i], width: 2.2 });
        circ.css('cursor', 'pointer');
        circ.on('mousemove', function (e) { showTooltip('Circle x² + y² = r²  (radius r)', e); })
          .on('mouseleave', hideTooltip)
          .on('click', function () {
            showPopup('The circle', 'Every point on this circle satisfies x² + y² = r². A solution of the system must lie on both the circle and the line at once, so the solutions are exactly the shared points.');
          });

        // intersection dots
        var cnt = countFor(dU);
        var dots = [];
        if (cnt === 1) dots.push(P0);
        else if (cnt === 2) {
          var h = Math.sqrt(Math.max(0, R * R - d * d));
          dots.push({ x: P0.x - U.x * h, y: P0.y - U.y * h });
          dots.push({ x: P0.x + U.x * h, y: P0.y + U.y * h });
        }
        dots.forEach(function (p, k) {
          var dot = g.circle(cnt === 1 ? 9.5 : (k === 1 ? 10 : 8.5)).center(p.x, p.y).fill('#000');
          dot.css('cursor', 'pointer');
          dot.on('mousemove', function (e) { showTooltip(cnt === 1 ? 'Tangency point — the two solutions have merged' : 'Intersection point — one solution of the system', e); })
            .on('mouseleave', hideTooltip)
            .on('click', function () {
              showPopup('Shared point', cnt === 1
                ? 'At tangency the quadratic has a double root: the two intersection points coincide, so the system has exactly one solution.'
                : 'This point lies on both the circle and the line, so its coordinates satisfy both equations — one of the two solutions.');
            });
        });

        // distance d and radius r on the active panel
        if (showDist && i === active) {
          var dl = g.line(cx, CY, P0.x, P0.y).stroke({ color: '#7a7a7a', width: 1.6, dasharray: '5,4' });
          dl.css('cursor', 'pointer');
          dl.on('mousemove', function (e) { showTooltip('d = perpendicular distance from centre to line = ' + dU.toFixed(2) + ' r', e); })
            .on('mouseleave', hideTooltip)
            .on('click', function () {
              showPopup('The deciding quantity', 'd is the perpendicular distance from the circle centre to the line. Compare it with r: d > r (miss), d = r (tangent), d < r (secant). Nothing else matters.');
            });
          var rl = g.line(cx, CY, cx + U.x * R, CY + U.y * R).stroke({ color: '#b5b5b5', width: 2.2 });
          g.circle(4).center(cx, CY).fill('#555');
          if (d > 14) label(g, 'd', (cx + P0.x) / 2 - 8, (CY + P0.y) / 2 - 9, { size: 14, italic: true, fill: '#555', halo: true, family: 'Georgia, serif' });
          label(g, 'r', cx + U.x * R * 0.58 + 10, CY + U.y * R * 0.58 + 6, { size: 14, italic: true, fill: '#8a8a8a', halo: true, family: 'Georgia, serif' });
        }

        if (showDist) {
          if (i === active) g.transform({ scale: 1.05, origin: [cx, CY] });
          else g.opacity(0.3);
        }

        // caption (unscaled)
        var cg = geo.group();
        var capText = (i === active) ? CAP[cnt] : CAP[i];
        label(cg, capText, cx, 240, { size: 19, family: 'Georgia, "Times New Roman", serif', fill: '#1a1a1a' });
        if (showDist && i !== active) cg.opacity(0.3);

        // readout below active caption
        if (showDist && i === active) {
          var cmp = cnt === 0 ? '>' : (cnt === 1 ? '=' : '<');
          var words = cnt === 1 ? '1 solution' : cnt + ' solutions';
          label(geo, 'd = ' + dU.toFixed(2) + ' r   ' + cmp + '   r   →   ' + words,
            cx, 268, { size: 12.5, fill: COUNTCOL[cnt] });
        }
      })(i);
    }
  }

  // ── algebraic view ────────────────────────────────────────────────────
  function renderAlgebraic() {
    var dU = offset;
    var cnt = countFor(dU);
    var b = 2 * dU;                    // r = 1, m = √3  ⇒  d = b/2
    var B = 2 * Math.sqrt(3) * b;      // 2mb
    var C = b * b - 1;                 // b² − r²
    var D = 16 - 4 * b * b;
    if (cnt === 1) D = 0;

    alg.rect(640, 234).move(40, 26).radius(10).fill('#ffffff').stroke({ color: '#dcdfe3', width: 1.4 });

    // thumbnail
    var tcx = 140, tcy = 132, tr = 44;
    var d = dU * tr;
    var P0 = { x: tcx + N.x * d, y: tcy + N.y * d };
    var tg = alg.group();
    drawLineInBox(tg, P0, { x0: 62, x1: 220, y0: 48, y1: 216 }, 1.8);
    tg.circle(2 * tr).center(tcx, tcy).fill('none').stroke({ color: COLORS[cnt === 0 ? 0 : (cnt === 1 ? 1 : 2)], width: 2 });
    if (cnt === 1) tg.circle(7).center(P0.x, P0.y).fill('#000');
    else if (cnt === 2) {
      var h = Math.sqrt(Math.max(0, tr * tr - d * d));
      tg.circle(7).center(P0.x - U.x * h, P0.y - U.y * h).fill('#000');
      tg.circle(7).center(P0.x + U.x * h, P0.y + U.y * h).fill('#000');
    }
    tg.line(tcx, tcy, P0.x, P0.y).stroke({ color: '#7a7a7a', width: 1.4, dasharray: '4,3' });
    tg.circle(3.5).center(tcx, tcy).fill('#555');
    label(alg, 'd = ' + dU.toFixed(2) + ' r', tcx, 232, { size: 12, fill: '#555' });

    var X = 445;
    label(alg, 'Circle:   x² + y² = r²      (take r = 1)', X, 58, { size: 15.5, family: 'Georgia, serif', fill: '#1a1a1a' });
    label(alg, 'Line:   y = m x + b      (m = √3,   b = 2d = ' + b.toFixed(2) + ')', X, 88, { size: 15.5, family: 'Georgia, serif', fill: '#1a1a1a' });
    label(alg, 'Substitute:   (1 + m²) x² + 2mb x + (b² − r²) = 0', X, 124, { size: 15.5, family: 'Georgia, serif', fill: '#1a1a1a' });
    label(alg, '4 x²  +  ' + B.toFixed(2) + ' x  +  ' + C.toFixed(2) + '  =  0', X, 152, { size: 15, family: 'Georgia, serif', fill: '#444' });

    var dTxt = 'D = 4m²b² − 4(1 + m²)(b² − r²) = 16 − 4b² = ' + D.toFixed(2);
    label(alg, dTxt, X, 190, { size: 15.5, family: 'Georgia, serif', fill: COUNTCOL[cnt] });

    var badgeTxt = (cnt === 1 ? '1 solution' : cnt + ' solutions');
    var bw = 168;
    var br = alg.rect(bw, 32).center(X, 228).radius(16)
      .fill(cnt === 0 ? '#fbe9e7' : (cnt === 1 ? '#eeeeee' : '#e6f6e9'))
      .stroke({ color: COUNTCOL[cnt], width: 1.3 });
    label(alg, badgeTxt, X, 228, { size: 16, family: 'Georgia, serif', fill: COUNTCOL[cnt] });
    br.css('cursor', 'pointer');
    br.on('mousemove', function (e) { showTooltip('Sign of D ⇔ number of real roots ⇔ number of shared points', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Discriminant = geometry', 'With r = 1 and m = √3 the discriminant simplifies to D = 16 − 4b² = 16(1 − d²). So D < 0 exactly when d > r, D = 0 exactly when d = r, and D > 0 exactly when d < r. The algebraic test and the distance test are the same test.');
      });
  }

  function render() {
    geo.clear(); alg.clear();
    if (mode === 'alg') { geo.hide(); alg.show(); renderAlgebraic(); }
    else { alg.hide(); geo.show(); renderGeometric(); }
    var lbl = document.getElementById('activeCaseLabel');
    if (lbl) lbl.textContent = 'Active panel: ' + ['left (orange)', 'centre (green)', 'right (red)'][active] +
      ' — slider drives this one';
  }

  // ── interaction handlers (global) ─────────────────────────────────────
  window.update_lineOffset = function (v) { offset = +v; render(); };
  window.trigger_caseStepper = function () {
    active = (active + 1) % 3;
    offset = CANON[active];
    var inp = document.getElementById('lineOffsetInput');
    inp.value = offset;
    document.getElementById('lineOffsetVal').value = offset.toFixed(2);
    render();
  };
  window.toggle_viewMode = function (on) { mode = on ? 'alg' : 'geo'; render(); };
  window.toggle_showDistance = function (on) { showDist = !!on; render(); };

  // ── demo steps ────────────────────────────────────────────────────────
  var STEPS = [
    { title: 'Three possible outcomes', narration: "Three circles, three parallel lines with the same slope. Only the line's distance from the center changes, and with it the number of shared points.", state: { viewMode: 'Geometric', caseStepper: 'no solution', showDistance: false, lineOffset: 1.6 } },
    { title: 'No solutions: the line misses', narration: 'The line passes entirely outside the orange circle. No point satisfies both equations, so the system has no solution.', state: { caseStepper: 'no solution', lineOffset: 1.6, showDistance: true, viewMode: 'Geometric' } },
    { title: 'One solution: tangency', narration: 'Slide the line inward until d equals exactly the radius. The two would-be crossings merge into a single tangency point, marked in black.', state: { caseStepper: 'one solution (tangent)', lineOffset: 1, showDistance: true, viewMode: 'Geometric' } },
    { title: 'Two solutions: a secant', narration: 'Push the line closer still. It now cuts the circle, entering at the lower left and exiting at the upper right — two marked intersection points, two solutions.', state: { caseStepper: 'two solutions (secant)', lineOffset: 0.4, showDistance: true, viewMode: 'Geometric' } },
    { title: 'The algebra behind the picture', narration: 'Substituting the line into the circle gives a quadratic. Its discriminant is negative, zero, or positive exactly when the line misses, touches, or cuts the circle.', state: { viewMode: 'Algebraic', lineOffset: 0.4, caseStepper: 'two solutions (secant)', showDistance: true } },
    { title: 'Sweep and watch the discriminant', narration: 'Drag the offset slider across the full range and watch the discriminant change sign at the tangent case — the geometric and algebraic tests are the same test.', state: { viewMode: 'Algebraic', lineOffset: 1, showDistance: true } }
  ];
  var CASE_MAP = { 'no solution': 0, 'one solution (tangent)': 1, 'two solutions (secant)': 2 };
  var step = 0;

  function applyState(s) {
    if (s.viewMode != null) { mode = (s.viewMode === 'Algebraic') ? 'alg' : 'geo'; document.getElementById('viewModeInput').checked = (mode === 'alg'); }
    if (s.caseStepper != null && CASE_MAP[s.caseStepper] != null) active = CASE_MAP[s.caseStepper];
    if (s.showDistance != null) { showDist = !!s.showDistance; document.getElementById('showDistanceInput').checked = showDist; }
    if (s.lineOffset != null) {
      offset = +s.lineOffset;
      document.getElementById('lineOffsetInput').value = offset;
      document.getElementById('lineOffsetVal').value = offset.toFixed(2);
    }
    render();
  }
  function showStep(i) {
    step = Math.max(0, Math.min(STEPS.length - 1, i));
    var s = STEPS[step];
    document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (step + 1) + ' / ' + STEPS.length;
    applyState(s.state);
  }
  window.prevStep = function () { showStep(step - 1); };
  window.nextStep = function () { showStep(step + 1); };

  showStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

